import { useMemo } from 'react';

import { ChartLegendItem } from 'components';

import { WaterfallSectionData } from '../../types';

export const useWaterfallDatasets = (
  data: WaterfallSectionData | undefined,
  waterfallVariant: 'large' | 'small',
) => {
  const legendItems = useMemo(() => {
    if (!data?.legend) return [];
    return data?.legend?.map((item) => ({
      label: item.label,
      color: '#0000008F',
      shape: 'rectangle',
      size: 'medium',
      decoration: item.label.includes('LE') ? 'dash' : 'none',
    }));
  }, [data]) as ChartLegendItem[];

  const shouldShowLegend = useMemo(() => {
    return (
      legendItems.length > 0 &&
      (data?.[waterfallVariant]?.stripedIndexes?.length ?? 0) > 0
    );
  }, [legendItems, data, waterfallVariant]);

  return {
    legendItems,
    shouldShowLegend,
  };
};
